From 1f9885732248d22f788e4992c739a98c88ab8a55 Mon Sep 17 00:00:00 2001
From: Luo Haiyang <luo.haiyang@zte.com.cn>
Date: Thu, 26 Mar 2026 14:19:53 +0800
Subject: [PATCH] tracing: Fix potential deadlock in cpu hotplug with osnoise

The following sequence may leads deadlock in cpu hotplug:

    task1        task2        task3

diff --git a/kernel/trace/trace_osnoise.c b/kernel/trace/trace_osnoise.c
index dee610e465b9..be6cf0bb3c03 100644
--- a/kernel/trace/trace_osnoise.c
+++ b/kernel/trace/trace_osnoise.c
@@ -2073,8 +2073,8 @@ static void osnoise_hotplug_workfn(struct work_struct *dummy)
 	if (!osnoise_has_registered_instances())
 		return;

-	guard(mutex)(&interface_lock);
 	guard(cpus_read_lock)();
+	guard(mutex)(&interface_lock);

 	if (!cpu_online(cpu))
 		return;
@@ -2237,11 +2237,11 @@ static ssize_t osnoise_options_write(struct file *filp, const char __user *ubuf,
 	if (running)
 		stop_per_cpu_kthreads();

-	mutex_lock(&interface_lock);
 	/*
 	 * avoid CPU hotplug operations that might read options.
 	 */
 	cpus_read_lock();
+	mutex_lock(&interface_lock);

 	retval = cnt;

@@ -2257,8 +2257,8 @@ static ssize_t osnoise_options_write(struct file *filp, const char __user *ubuf,
 			clear_bit(option, &osnoise_options);
 	}

-	cpus_read_unlock();
 	mutex_unlock(&interface_lock);
+	cpus_read_unlock();

 	if (running)
 		start_per_cpu_kthreads();
@@ -2345,16 +2345,16 @@ osnoise_cpus_write(struct file *filp, const char __user *ubuf, size_t count,
 	if (running)
 		stop_per_cpu_kthreads();

-	mutex_lock(&interface_lock);
 	/*
 	 * osnoise_cpumask is read by CPU hotplug operations.
 	 */
 	cpus_read_lock();
+	mutex_lock(&interface_lock);

 	cpumask_copy(&osnoise_cpumask, osnoise_cpumask_new);

-	cpus_read_unlock();
 	mutex_unlock(&interface_lock);
+	cpus_read_unlock();

 	if (running)
 		start_per_cpu_kthreads();
-- 
2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
tracing: Fix potential deadlock in cpu hotplug with osnoise

The following sequence may leads deadlock in cpu hotplug:

    task1        task2        task3
    -----        -----        -----

 mutex_lock(&interface_lock)

            [CPU GOING OFFLINE]

            cpus_write_lock();
            osnoise_cpu_die();
              kthread_stop(task3);
                wait_for_completion();

                      osnoise_sleep();
                        mutex_lock(&interface_lock);

 cpus_read_lock();

 [DEAD LOCK]

Fix by swap the order of cpus_read_lock() and mutex_lock(&interface_lock).

Cc: stable@vger.kernel.org
Cc: <mathieu.desnoyers@efficios.com>
Cc: <zhang.run@zte.com.cn>
Cc: <yang.tao172@zte.com.cn>
Cc: <ran.xiaokai@zte.com.cn>
Fixes: bce29ac9ce0bb ("trace: Add osnoise tracer")
Link: https://patch.msgid.link/20260326141953414bVSj33dAYktqp9Oiyizq8@zte.com.cn
Reviewed-by: Masami Hiramatsu (Google) <mhiramat@kernel.org>
Signed-off-by: Luo Haiyang <luo.haiyang@zte.com.cn>
Signed-off-by: Steven Rostedt (Google) <rostedt@goodmis.org>

Here is the root cause:
Inconsistent lock ordering between the CPU hotplug work function (`osnoise_hotplug_workfn`) and the `osnoise_options_write`/`osnoise_cpus_write` functions. The hotplug path acquired `interface_lock` before `cpus_read_lock`, while the write paths acquired `cpus_read_lock` after `interface_lock`, creating a potential circular wait deadlock when multiple threads execute these paths concurrently.

Here is the patch:
 #ifdef CONFIG_HOTPLUG_CPU
 static void osnoise_hotplug_workfn(struct work_struct *dummy)
 {
 	unsigned int cpu = smp_processor_id();

 	guard(mutex)(&trace_types_lock);

 	if (!osnoise_has_registered_instances())
 		return;

-	guard(mutex)(&interface_lock);
 	guard(cpus_read_lock)();
+	guard(mutex)(&interface_lock);

 	if (!cpu_online(cpu))
 		return;

 	if (!cpumask_test_cpu(cpu, &osnoise_cpumask))
 		return;

 	start_kthread(cpu);
 }

  */
 static ssize_t osnoise_options_write(struct file *filp, const char __user *ubuf,
 				     size_t cnt, loff_t *ppos)
 {
 	int running, option, enable, retval;
 	char buf[256], *option_str;

 	if (cnt >= 256)
 		return -EINVAL;

 	if (copy_from_user(buf, ubuf, cnt))
 		return -EFAULT;

 	buf[cnt] = 0;

 	if (strncmp(buf, "NO_", 3)) {
 		option_str = strstrip(buf);
 		enable = true;
 	} else {
 		option_str = strstrip(&buf[3]);
 		enable = false;
 	}

 	option = match_string(osnoise_options_str, OSN_MAX, option_str);
 	if (option < 0)
 		return -EINVAL;

 	/*
 	 * trace_types_lock is taken to avoid concurrency on start/stop.
 	 */
 	mutex_lock(&trace_types_lock);
 	running = osnoise_has_registered_instances();
 	if (running)
 		stop_per_cpu_kthreads();

-	mutex_lock(&interface_lock);
 	/*
 	 * avoid CPU hotplug operations that might read options.
 	 */
 	cpus_read_lock();
+	mutex_lock(&interface_lock);

 	retval = cnt;

 	if (enable) {
 		if (option == OSN_DEFAULTS)
 			osnoise_options = OSN_DEFAULT_OPTIONS;
 		else
 			set_bit(option, &osnoise_options);
 	} else {
 		if (option == OSN_DEFAULTS)
 			retval = -EINVAL;
 		else
 			clear_bit(option, &osnoise_options);
 	}

-	cpus_read_unlock();
 	mutex_unlock(&interface_lock);
+	cpus_read_unlock();

 	if (running)
 		start_per_cpu_kthreads();
 	mutex_unlock(&trace_types_lock);

 	return retval;
 }

  */
 static ssize_t
 osnoise_cpus_write(struct file *filp, const char __user *ubuf, size_t count,
 		   loff_t *ppos)
 {
 	cpumask_var_t osnoise_cpumask_new;
 	int running, err;
 	char *buf __free(kfree) = NULL;

 	if (count < 1)
 		return 0;

 	buf = memdup_user_nul(ubuf, count);
 	if (IS_ERR(buf))
 		return PTR_ERR(buf);

 	if (!zalloc_cpumask_var(&osnoise_cpumask_new, GFP_KERNEL))
 		return -ENOMEM;

 	err = cpulist_parse(buf, osnoise_cpumask_new);
 	if (err)
 		goto err_free;

 	/*
 	 * trace_types_lock is taken to avoid concurrency on start/stop.
 	 */
 	mutex_lock(&trace_types_lock);
 	running = osnoise_has_registered_instances();
 	if (running)
 		stop_per_cpu_kthreads();

-	mutex_lock(&interface_lock);
 	/*
 	 * osnoise_cpumask is read by CPU hotplug operations.
 	 */
 	cpus_read_lock();
+	mutex_lock(&interface_lock);

 	cpumask_copy(&osnoise_cpumask, osnoise_cpumask_new);

-	cpus_read_unlock();
 	mutex_unlock(&interface_lock);
+	cpus_read_unlock();

 	if (running)
 		start_per_cpu_kthreads();
 	mutex_unlock(&trace_types_lock);

 	free_cpumask_var(osnoise_cpumask_new);
 	return count;

 err_free:
 	free_cpumask_var(osnoise_cpumask_new);

 	return err;
 }



